const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C={ink:'#17384a',blue:'#407ea3',cyan:'#60bfce',gold:'#e9b655',silicon:'#a8bac5',resist:'#d88072',green:'#66a897',pale:'#edf4f5'};
const rect=(x,y,w,h,f=C.silicon,rx=3)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}" stroke="${C.ink}" stroke-width="1.5"/>`;
const circle=(x,y,r,f=C.cyan)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" stroke="${C.ink}" stroke-width="1.4"/>`;
const line=(x,y,a,b,color=C.ink,width=2)=>`<line x1="${x}" y1="${y}" x2="${a}" y2="${b}" stroke="${color}" stroke-width="${width}"/>`;
const path=(d,fill='none',stroke=C.ink,width=2)=>`<path d="${d}" fill="${fill}" stroke="${stroke}" stroke-width="${width}"/>`;
const text=(x,y,t,size=13,fill=C.ink,anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" font-family="system-ui, sans-serif" fill="${fill}" text-anchor="${anchor}">${esc(t)}</text>`;
const arrow=(x,y,a,b,color=C.blue)=>{const ang=Math.atan2(b-y,a-x),s=8;return line(x,y,a,b,color,2.5)+path(`M ${a-s*Math.cos(ang-.5)} ${b-s*Math.sin(ang-.5)} L ${a} ${b} L ${a-s*Math.cos(ang+.5)} ${b-s*Math.sin(ang+.5)}`,'none',color,2.5)};
const many=(n,fn)=>Array.from({length:n},(_,i)=>fn(i)).join('');
const wafer=(x=300,y=170)=>`<ellipse cx="${x}" cy="${y}" rx="110" ry="55" fill="${C.blue}" stroke="${C.ink}" stroke-width="2"/>`+many(7,i=>line(x-78+i*26,y-32,x-78+i*26,y+32,C.pale,1))+many(3,i=>line(x-85,y-26+i*26,x+85,y-26+i*26,C.pale,1));
const base=()=>rect(135,220,330,25);
const label=(zh,a,b)=>zh?a:b;
