export function semiconductorVisualFamily(courseId){return SEMICONDUCTOR_SUBJECTS[courseId]?.family??null;}
export function renderSemiconductorVisual(courseId,{zh=true,mode='full'}={}){
const subject=SEMICONDUCTOR_SUBJECTS[courseId];if(!subject)return '';
const f=subject.family,e=courseId==='a045'?['導引邊界與自組裝相分離','Guides and self-assembled phase separation','排列缺陷與圖案轉移需分開檢查','Check ordering defects and pattern transfer separately']:courseId==='a046'?['模具、薄膜與圖案複製','Stamp, film and pattern replication','殘留層、填充與脫模缺陷','Residual layer, filling and release defects']:['a035','a047'].includes(courseId)?['電子束、光阻與寫入路徑','Electron beam, resist and write path','散射、劑量與拼接需驗證','Verify scattering, dose and stitching']:courseId==='a089'?['受壓膜片、腔體與讀出','Diaphragm, cavity and readout','膜片應力與壓力響應需校準','Calibrate diaphragm stress and pressure response']:courseId==='a003'?['晶棒、多線鋸與切片','Ingot, wire saw and slicing','切片厚度、翹曲與表面損傷','Slice thickness, bow and surface damage']:courseId==='a084'?['磊晶堆疊與發光層','Epitaxial stack and emitting layer','材料缺陷與非輻射複合','Material defects and nonradiative recombination']:EXPLANATIONS[f],title=zh?subject.title:subject.titleEn,description=zh?`${e[0]}。${e[2]}。原創概念圖；非比例、非施工圖。`:`${e[1]}. ${e[3]}. Original concept diagram; not to scale or a fabrication drawing.`;
const simple=mode==='icon'||mode==='compact';
return `<svg xmlns="http://www.w3.org/2000/svg" class="semiconductor-subject-visual" viewBox="0 0 600 340" role="img" aria-label="${esc(title+' — '+description)}" data-course="${esc(courseId)}" data-family="${f}" data-original="true"><title>${esc(title)}</title><desc>${esc(description)}</desc><rect width="600" height="340" rx="22" fill="${C.pale}"/>${text(27,32,courseId.toUpperCase(),12,C.blue,'start')}${text(572,32,zh?'原創概念圖 · 非比例':'ORIGINAL CONCEPT · NOT TO SCALE',11,C.blue,'end')}${text(300,57,title,zh?16:13)}<g data-geometry="${f}">${geometry(f,zh,courseId)}</g>${simple?'':text(300,313,zh?e[0]:e[1],16)}</svg>`;
}
